#include <bits/stdc++.h>
using namespace std;

int uniqueColors(const vector<int>& colors, int start, int end) {
    vector<bool> seen(24, false);
    int total = 0;
    for (int i = start; i <= end; i++) {
        int c = colors[i];
        if (!seen[c]) {
            seen[c] = true;
            total++;
        }
    }
    return total;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int a, b, l, r;
    cin >> a >> b >> l >> r;
    l -= 1;
    r -= 1;
    int sumAB = a + b;
    int repeatCount = 4;
    vector<int> patternArr(sumAB * repeatCount);
    int shiftH = l / sumAB;
    l -= shiftH * sumAB;
    r -= shiftH * sumAB;
    int segmentSize = (r - l + 1) / sumAB;
    if (segmentSize > 2) r -= (segmentSize - 2) * sumAB;
    int delta = max(a - b, 1);
    for (int repIdx = 0; repIdx < repeatCount; repIdx++) {
        for (int k = 0; k < a - delta; k++)
            patternArr[sumAB * repIdx + k] = k;
        for (int k = 0; k < delta; k++)
            patternArr[sumAB * repIdx + a - delta + k] = (repIdx % 2 == 0) ? a - delta + k : a + k;
    }
    int minColors = a + a;
    for (int shiftAIdx = 1; shiftAIdx <= delta; shiftAIdx++) {
        for (int k = 0; k < b; k++)
            patternArr[a + k] = patternArr[a - shiftAIdx];
        for (int shiftBIdx1 = 1; shiftBIdx1 <= delta; shiftBIdx1++) {
            for (int k = 0; k < b; k++)
                patternArr[sumAB + a + k] = patternArr[sumAB + a - shiftBIdx1];
            for (int shiftBIdx2 = 1; shiftBIdx2 <= delta; shiftBIdx2++) {
                for (int k = 0; k < b; k++)
