                    for (int k = 0; k < b; k++)
                        patternArr[3 * sumAB + a + k] = patternArr[3 * sumAB + a - shiftBIdx3];
                    minColors = min(minColors, uniqueColors(patternArr, l, r));
                }
            }
        }
    }
    cout << minColors << "\n";
    return 0;
}

